import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array to efficiently 
    check the presence of items with a configurable false positive rate.

    The optimal bit array size and number of hash functions are calculated 
    based on the expected number of items and desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.size = self._optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_count(self.size, expected_items)
        self.bit_array = [0] * self.size

    def add(self, item: str) -> None:
        for i in range(self.hash_count):
            hash_value = self._hash(item, i)
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        for i in range(self.hash_count):
            hash_value = self._hash(item, i)
            if self.bit_array[hash_value] == 0:
                return False
        return True

    def _optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int(round(m / n * math.log(2))))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash value for the item using a given seed."""
        # Combine the seed with the item for unique hashing
        hash_input = f"{item}{seed}".encode('utf-8')
        # Use SHA-256 and take the modulus with the bit array size
        hash_output = hashlib.sha256(hash_input).hexdigest()
        return int(hash_output, 16) % self.size

