class BloomFilter:
    """A simple Bloom Filter implementation to test membership with a specified false positive rate.

    This implementation calculates the optimal size of the bit array and the number of hash functions
    based on the expected number of items and the desired false positive rate. It uses basic bit manipulation
    to maintain the bit array and hashlib for consistent hash computation.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the size of the bit array (m) and number of hash functions (k)
        self.size = self._calculate_size()
        self.hash_count = self._calculate_hash_count()

        # Create the bit array initialized to 0
        self.bit_array = [0] * self.size

    def _calculate_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil((self.expected_items * math.log(self.false_positive_rate)) / math.log(1 / (math.pow(2, math.log(2)))))

    def _calculate_hash_count(self) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate k hash values for the item using hashlib."""
        hash_values = []
        for i in range(self.hash_count):
            # Create a unique hash for each hash function
            hash_result = hashlib.md5(f"{item}{i}".encode()).hexdigest()
            hash_index = int(hash_result, 16) % self.size
            hash_values.append(hash_index)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[index] for index in self._hashes(item))

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter is a space-efficient probabilistic data structure 
    used to test whether an element is a member of a set. 
    False positives are possible, but false negatives are not.

    This implementation uses a bit array to represent the set and 
    multiple hash functions to compute indices for items.

    The optimal size of the bit array and the number of hash functions 
    are computed based on the expected number of items and the desired 
    false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._optimal_bit_array_size()
        self.hash_count = self._optimal_number_of_hashes()
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self) -> int:
        """Calculates the optimal bit array size based on expected_items and false_positive_rate."""
        return max(1, int(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2)))

    def _optimal_number_of_hashes(self) -> int:
        """Calculates the optimal number of hash functions for the Bloom filter."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generates multiple hash values for the given item."""
        hashes = []
        for i in range(self.hash_count):
            hash_result = int(hashlib.md5((item + str(i)).encode('utf-8')).hexdigest(), 16)
            indexes = hash_result % self.size
            hashes.append(indexes)
        return hashes

    def add(self, item: str) -> None:
        """Adds an item to the Bloom filter by setting the corresponding bits."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Checks if an item might be in the Bloom filter."""
        return all(self.bit_array[index] for index in self._hashes(item))
